INSERT INTO public.personality_details (type, locale, details) VALUES
('INTJ', 'en', '{"name":"Architect","introduction":"It can be lonely at the top. As one of the rarest personality types – and one of the most capable – Architects (INTJ) know this all too well. Rational and quick-witted, they pride themselves on their ability to think for themselves, not to mention their uncanny knack for seeing right through phoniness and hypocrisy. But because their minds are never at rest, Architects may struggle to find people who can keep up with their nonstop analysis of everything around them.","strengths_weaknesses":{"title":"Strengths & Weaknesses","introduction":"Architects are independent, self-sufficient, and motivated by their own high standards. They don't need external validation or social approval to feel good about themselves. This gives them a unique sense of freedom and a powerful drive to achieve their goals.","strengths":[{"title":"Rational","description":"For Architects, rationality is king. They approach every situation with a desire to understand the underlying principles and patterns. This allows them to make sound, logical decisions, unclouded by emotion or bias."},{"title":"Informed","description":"Few personality types are as dedicated to learning and accumulating knowledge as Architects. They are voracious readers and tireless researchers, always seeking to expand their understanding of the world. This makes them highly informed and capable individuals."},{"title":"Independent","description":"Architects are not ones to follow the crowd. They trust their own judgment and are not afraid to go against the grain. This independence allows them to forge their own path and come up with innovative solutions to complex problems."},{"title":"Determined","description":"When Architects set a goal, they are relentless in their pursuit of it. They have a remarkable ability to stay focused and motivated, even in the face of significant obstacles. Their determination is a key factor in their success."},{"title":"Curious","description":"Architects have a deep-seated curiosity about the world. They are always asking "why" and are not satisfied with easy answers. This insatiable curiosity fuels their quest for knowledge and drives them to explore new ideas and possibilities."},{"title":"Versatile","description":"Thanks to their broad knowledge base and their ability to see the big picture, Architects are often able to excel in a wide range of fields. They can quickly grasp complex systems and are adept at applying their knowledge to solve practical problems."}],"weaknesses":[{"title":"Arrogant","description":"Architects' confidence in their own intellectual abilities can sometimes cross the line into arrogance. They may be dismissive of others' opinions, especially if they perceive them to be less rational or informed. This can make them difficult to work with and can alienate them from others."},{"title":"Dismissive of Emotions","description":"Architects tend to view emotions as irrational and messy. They may have difficulty understanding and responding to the emotional needs of others, which can make them appear cold or insensitive. This can create challenges in their personal relationships."},{"title":"Overly Critical","description":"With their analytical minds, Architects can be overly critical of both themselves and others. They have high standards and can be quick to point out flaws and imperfections. While this can be a strength in some contexts, it can also be a source of stress and conflict."},{"title":"Combative","description":"Architects enjoy a good intellectual debate and are not afraid to challenge others' ideas. However, their love of argumentation can sometimes come across as combative or confrontational. They may not realize that their passion for debate can be intimidating to others."},{"title":"Socially Clueless","description":"Architects can be so focused on their own thoughts and ideas that they neglect the social niceties that are important for building relationships. They may have difficulty with small talk and may not always pick up on social cues. This can make it hard for them to connect with others on a personal level."}]},"romantic_relationships":{"title":"Romantic Relationships","introduction":"Architects approach romance the way they do most things: with a strategic and goal-oriented mindset. They are not interested in fleeting attractions or casual flings. Instead, they seek a partner who can meet them on an intellectual level and who shares their commitment to self-improvement. They value directness and honesty in a relationship and have little patience for games or manipulation.","conclusion":"Finding a compatible partner can be a challenge for Architects, but when they do, they are loyal and devoted. They are willing to put in the effort to build a strong and lasting relationship, and they are committed to helping their partner grow and develop. For Architects, a successful relationship is a true partnership of equals."},"friendships":{"title":"Friendships","introduction":"Architects don't have a wide circle of friends, but the friendships they do have are often deep and long-lasting. They are drawn to people who are intelligent, independent, and who share their love of ideas. They are not interested in superficial relationships and prefer to spend their time with people who can engage them in meaningful conversations.","conclusion":"For Architects, friendship is a meeting of the minds. They are loyal and supportive friends who are always willing to help their friends think through complex problems. They may not be the most emotionally expressive friends, but they show their care through their actions and their unwavering support."},"parenthood":{"title":"Parenthood","introduction":"As parents, Architects are focused on raising children who are independent, self-sufficient, and capable of thinking for themselves. They encourage their children to be curious and to ask questions, and they provide them with the resources and support they need to learn and grow. They are not overly authoritarian parents and prefer to treat their children as rational individuals who are capable of making their own decisions.","conclusion":"Architects take their role as parents very seriously. They are committed to providing their children with the best possible start in life, and they are willing to put in the time and effort to help their children reach their full potential. They are proud of their children's accomplishments and are always there to offer them guidance and support."},"career_paths":{"title":"Career Paths","introduction":"Architects are drawn to careers that allow them to use their analytical skills and their love of knowledge to solve complex problems. They are not interested in routine or repetitive work and prefer careers that offer them a great deal of autonomy and intellectual challenge. They are often found in fields such as science, technology, engineering, and mathematics (STEM), but they can also be successful in any field that requires strategic thinking and a deep understanding of complex systems.","conclusion":"Whatever career path they choose, Architects are likely to be successful. Their intelligence, determination, and innovative thinking make them valuable assets in any organization. They are not content to simply do their job; they are always looking for ways to improve processes, solve problems, and make a lasting impact."}}'),
('INTP', 'en', '{"name":"Logician","introduction":"Logicians (INTP) are known for their brilliant theories and unrelenting logic. They are fascinated by logical analysis, systems, and design. They are driven to understand the unifying principles of the universe. They can appear pensive and detached to others, as they are often lost in thought.","strengths_weaknesses":{"title":"Strengths & Weaknesses","introduction":"Logicians are proud of their knowledge and intellectual prowess.","strengths":[{"title":"Analytical","description":"They can analyze complex problems with ease."},{"title":"Objective","description":"They are impartial and base decisions on facts."},{"title":"Imaginative","description":"They have a creative and innovative mind."}],"weaknesses":[{"title":"Insensitive","description":"They can be unaware of others' feelings."},{"title":"Absent-minded","description":"They often get lost in their own thoughts."},{"title":"Condescending","description":"They can look down on those they see as less intelligent."}]},"romantic_relationships":{"title":"Romantic Relationships","introduction":"In relationships, Logicians seek a meeting of minds.","conclusion":"They value intellectual connection above all else."},"friendships":{"title":"Friendships","introduction":"Logicians prefer a small circle of close friends.","conclusion":"They value deep, intellectual conversations."},"parenthood":{"title":"Parenthood","introduction":"As parents, Logicians encourage intellectual curiosity.","conclusion":"They teach their children to think for themselves."},"career_paths":{"title":"Career Paths","introduction":"Logicians thrive in careers that challenge their intellect.","conclusion":"They excel in scientific and technical fields."}}'),
('ENTJ', 'en', '{"name":"Commander","introduction":"Commanders (ENTJ) are natural-born leaders. They are decisive people who love momentum and accomplishment. They are charismatic, confident, and projecting authority, and can rally crowds to their common goal.","strengths_weaknesses":{"title":"Strengths & Weaknesses","introduction":"Commanders are driven to lead.","strengths":[{"title":"Efficient","description":"They find effective solutions to problems."},{"title":"Energetic","description":"They have a great deal of stamina and drive."},{"title":"Charismatic","description":"They can inspire and motivate others."}],"weaknesses":[{"title":"Stubborn","description":"They can be inflexible and unyielding."},{"title":"Impatient","description":"They have little tolerance for mistakes."},{"title":"Arrogant","description":"They can be overly confident in their abilities."}]},"romantic_relationships":{"title":"Romantic Relationships","introduction":"Commanders are passionate and committed partners.","conclusion":"They take their relationships very seriously."},"friendships":{"title":"Friendships","introduction":"Friendships with Commanders are built on mutual respect.","conclusion":"They enjoy surrounding themselves with capable people."},"parenthood":{"title":"Parenthood","introduction":"Commander parents aim to raise strong, independent children.","conclusion":"They set high standards for their children."},"career_paths":{"title":"Career Paths","introduction":"Commanders are drawn to leadership roles.","conclusion":"They are excellent managers and strategists."}}'),
('ENTP', 'en', '{"name":"Debater","introduction":"Debaters (ENTP) are the ultimate devil's advocate. They are smart and curious thinkers who cannot resist an intellectual challenge. They enjoy shredding arguments and beliefs and letting the ribbons drift in the wind for all to see.","strengths_weaknesses":{"title":"Strengths & Weaknesses","introduction":"Debaters thrive on mental sparring.","strengths":[{"title":"Quick-witted","description":"They think on their feet and respond rapidly."},{"title":"Knowledgeable","description":"They have a broad range of knowledge."},{"title":"Charismatic","description":"They are energetic and have a way with words."}],"weaknesses":[{"title":"Argumentative","description":"They can argue for the sake of it."},{"title":"Insensitive","description":"They may not consider the feelings of others."},{"title":"Intolerant","description":"They dislike practical, day-to-day tasks."}]},"romantic_relationships":{"title":"Romantic Relationships","introduction":"Debaters are enthusiastic and creative partners.","conclusion":"They enjoy exploring new ideas with a partner."},"friendships":{"title":"Friendships","introduction":"Friendships with Debaters are never dull.","conclusion":"They love to debate and discuss with friends."},"parenthood":{"title":"Parenthood","introduction":"Debater parents are open-minded and encouraging.","conclusion":"They foster a learning environment for their children."},"career_paths":{"title":"Career Paths","introduction":"Debaters excel in dynamic and challenging careers.","conclusion":"They are natural entrepreneurs and innovators."}}'),
('INFJ', 'en', '{"name":"Advocate","introduction":"Advocates (INFJ) are the quietest and most mystical of all the personality types. They have an inborn sense of idealism and morality, but what sets them apart is they are not idle dreamers. They are determined to make a positive impact on the world.","strengths_weaknesses":{"title":"Strengths & Weaknesses","introduction":"Advocates are driven by their values.","strengths":[{"title":"Creative","description":"They have a vivid imagination and strong intuition."},{"title":"Insightful","description":"They can see the best in people."},{"title":"Principled","description":"They have strong convictions and values."}],"weaknesses":[{"title":"Sensitive","description":"They can be easily hurt by criticism."},{"title":"Perfectionistic","description":"They can have unrealistically high standards."},{"title":"Private","description":"They are very private and hard to get to know."}]},"romantic_relationships":{"title":"Romantic Relationships","introduction":"Advocates seek deep, meaningful connections.","conclusion":"They are very loyal and committed partners."},"friendships":{"title":"Friendships","introduction":"Advocates are selective about their friends.","conclusion":"They prefer quality over quantity in friendships."},"parenthood":{"title":"Parenthood","introduction":"Advocate parents are nurturing and supportive.","conclusion":"They raise their children with strong values."},"career_paths":{"title":"Career Paths","introduction":"Advocates are drawn to careers that help others.","conclusion":"They excel as counselors, teachers, and artists."}}'),
('INFP', 'en', '{"name":"Mediator","introduction":"Mediators (INFP) are true idealists. They are poetic, kind, and altruistic people, always eager to help a good cause. They are guided by their principles rather than by logic, excitement, or practicality.","strengths_weaknesses":{"title":"Strengths & Weaknesses","introduction":"Mediators are guided by their inner moral compass.","strengths":[{"title":"Idealistic","description":"They have a strong sense of right and wrong."},{"title":"Creative","description":"They are imaginative and have a gift for language."},{"title":"Caring","description":"They are deeply empathetic and compassionate."}],"weaknesses":[{"title":"Unrealistic","description":"They can have impractical expectations."},{"title":"Self-isolating","description":"They may withdraw from others."},{"title":"Overly sensitive","description":"They can be very vulnerable to criticism."}]},"romantic_relationships":{"title":"Romantic Relationships","introduction":"Mediators seek a soulmate connection.","conclusion":"They are hopeless romantics."},"friendships":{"title":"Friendships","introduction":"Mediator friendships are deep and supportive.","conclusion":"They are loyal and understanding friends."},"parenthood":{"title":"Parenthood","introduction":"Mediator parents are warm and loving.","conclusion":"They create a nurturing environment for their children."},"career_paths":{"title":"Career Paths","introduction":"Mediators need a career with a purpose.","conclusion":"They are often writers, artists, or counselors."}}'),
('ENFJ', 'en', '{"name":"Protagonist","introduction":"Protagonists (ENFJ) are natural-born leaders, full of passion and charisma. They are often our politicians, our coaches, and our teachers, reaching out and inspiring others to achieve and to do good in the world.","strengths_weaknesses":{"title":"Strengths & Weaknesses","introduction":"Protagonists radiate authenticity and altruism.","strengths":[{"title":"Tolerant","description":"They are open-minded and reliable."},{"title":"Charismatic","description":"They are natural leaders who inspire others."},{"title":"Altruistic","description":"They are genuinely interested in helping others."}],"weaknesses":[{"title":"Overly idealistic","description":"They can be too trusting of others."},{"title":"Too selfless","description":"They may neglect their own needs."},{"title":"Struggle with criticism","description":"They can be very sensitive to conflict."}]},"romantic_relationships":{"title":"Romantic Relationships","introduction":"Protagonists are supportive and caring partners.","conclusion":"They are invested in their partner's growth."},"friendships":{"title":"Friendships","introduction":"Protagonists are the life of the party.","conclusion":"They have a wide circle of friends."},"parenthood":{"title":"Parenthood","introduction":"Protagonist parents are role models.","conclusion":"They are very involved in their children's lives."},"career_paths":{"title":"Career Paths","introduction":"Protagonists excel in people-oriented careers.","conclusion":"They are great leaders, counselors, and HR managers."}}'),
('ENFP', 'en', '{"name":"Campaigner","introduction":"Campaigners (ENFP) are true free spirits. They are the life of the party, but they are less interested in the sheer excitement and pleasure of the moment than they are in enjoying the social and emotional connections they make with others.","strengths_weaknesses":{"title":"Strengths & Weaknesses","introduction":"Campaigners are charming and independent.","strengths":[{"title":"Curious","description":"They are eager to explore new things."},{"title":"Observant","description":"They are good at noticing things about others."},{"title":"Energetic","description":"They are enthusiastic and popular."}],"weaknesses":[{"title":"Poor practical skills","description":"They dislike routine and administrative tasks."},{"title":"Overly emotional","description":"They can experience intense emotional swings."},{"title":"Easily stressed","description":"They can become overwhelmed easily."}]},"romantic_relationships":{"title":"Romantic Relationships","introduction":"Campaigners are passionate and adventurous partners.","conclusion":"They bring a lot of energy to their relationships."},"friendships":{"title":"Friendships","introduction":"Campaigners are fun and supportive friends.","conclusion":"They are always up for a new adventure."},"parenthood":{"title":"Parenthood","introduction":"Campaigner parents are creative and fun-loving.","conclusion":"They encourage their children's creativity."},"career_paths":{"title":"Career Paths","introduction":"Campaigners need a career that allows for creativity.","conclusion":"They are often journalists, actors, or marketers."}}'),
('ISTJ', 'en', '{"name":"Logistician","introduction":"Logisticians (ISTJ) are practical and fact-minded individuals. They are reliable and responsible, and their word is their bond. They take pride in their work and are dedicated to duty.","strengths_weaknesses":{"title":"Strengths & Weaknesses","introduction":"Logisticians are defined by their integrity.","strengths":[{"title":"Honest","description":"They are direct and truthful."},{"title":"Responsible","description":"They are dutiful and reliable."},{"title":"Calm","description":"They are calm and practical in nature."}],"weaknesses":[{"title":"Stubborn","description":"They are resistant to change."},{"title":"Insensitive","description":"They can accidentally hurt others' feelings."},{"title":"By-the-book","description":"They can be overly rigid."}]},"romantic_relationships":{"title":"Romantic Relationships","introduction":"Logisticians are loyal and dependable partners.","conclusion":"They build relationships on a foundation of trust."},"friendships":{"title":"Friendships","introduction":"Logistician friendships are based on reliability.","conclusion":"They are friends you can count on."},"parenthood":{"title":"Parenthood","introduction":"Logistician parents are traditional and responsible.","conclusion":"They provide a stable environment for their children."},"career_paths":{"title":"Career Paths","introduction":"Logisticians are the backbone of many organizations.","conclusion":"They excel as auditors, logisticians, and administrators."}}'),
('ISFJ', 'en', '{"name":"Defender","introduction":"Defenders (ISFJ) are true altruists. They are warm and unassuming people who are ready to protect the people they care about. They are efficient and responsible, and their kindness is felt by all.","strengths_weaknesses":{"title":"Strengths & Weaknesses","introduction":"Defenders are dedicated and warm protectors.","strengths":[{"title":"Supportive","description":"They are always ready to help."},{"title":"Reliable","description":"They are patient and hardworking."},{"title":"Observant","description":"They are good at remembering details about others."}],"weaknesses":[{"title":"Shy","description":"They can be very humble and self-effacing."},{"title":"Take things too personally","description":"They internalize conflict."},{"title":"Overload themselves","description":"They have a hard time saying no."}]},"romantic_relationships":{"title":"Romantic Relationships","introduction":"Defenders are loving and loyal partners.","conclusion":"They are deeply committed to their relationships."},"friendships":{"title":"Friendships","introduction":"Defender friendships are built on trust and support.","conclusion":"They are friends for life."},"parenthood":{"title":"Parenthood","introduction":"Defender parents are incredibly caring.","conclusion":"They are devoted to their children's well-being."},"career_paths":{"title":"Career Paths","introduction":"Defenders are drawn to careers in healthcare and social work.","conclusion":"They find joy in helping others."}}'),
('ESTJ', 'en', '{"name":"Executive","introduction":"Executives (ESTJ) are representatives of tradition and order. They are excellent administrators, unsurpassed at managing things or people. They are honest, dedicated, and dignified.","strengths_weaknesses":{"title":"Strengths & Weaknesses","introduction":"Executives are classic images of the model citizen.","strengths":[{"title":"Dedicated","description":"They are reliable and hardworking."},{"title":"Strong-willed","description":"They are confident and assertive."},{"title":"Direct","description":"They are honest and straightforward."}],"weaknesses":[{"title":"Inflexible","description":"They are resistant to unconventional ideas."},{"title":"Judgmental","description":"They can be critical of others."},{"title":"Difficulty expressing emotion","description":"They can appear insensitive."}]},"romantic_relationships":{"title":"Romantic Relationships","introduction":"Executives are stable and reliable partners.","conclusion":"They value security and tradition in relationships."},"friendships":{"title":"Friendships","introduction":"Executive friendships are based on shared values.","conclusion":"They are pillars of their communities."},"parenthood":{"title":"Parenthood","introduction":"Executive parents are organized and traditional.","conclusion":"They provide a structured environment for their children."},"career_paths":{"title":"Career Paths","introduction":"Executives are natural leaders and managers.","conclusion":"They excel in business, law, and the military."}}'),
('ESFJ', 'en', '{"name":"Consul","introduction":"Consuls (ESFJ) are extraordinarily caring, social, and popular people. They are the cheerleaders and the quarterbacks, setting the tone, taking the spotlight, and leading their teams forward to victory.","strengths_weaknesses":{"title":"Strengths & Weaknesses","introduction":"Consuls are the ultimate people persons.","strengths":[{"title":"Strong practical skills","description":"They are great at managing daily tasks."},{"title":"Dutiful","description":"They have a strong sense of responsibility."},{"title":"Loyal","description":"They are very supportive of their loved ones."}],"weaknesses":[{"title":"Worried about social status","description":"They are very sensitive to what others think."},{"title":"Inflexible","description":"They are uncomfortable with unconventional things."},{"title":"Vulnerable to criticism","description":"They can be easily hurt by disapproval."}]},"romantic_relationships":{"title":"Romantic Relationships","introduction":"Consuls are attentive and caring partners.","conclusion":"They love to take care of their loved ones."},"friendships":{"title":"Friendships","introduction":"Consuls are at the center of their social circles.","conclusion":"They are popular and outgoing."},"parenthood":{"title":"Parenthood","introduction":"Consul parents are loving and involved.","conclusion":"They are very hands-on with their children."},"career_paths":{"title":"Career Paths","introduction":"Consuls are drawn to careers that involve helping people.","conclusion":"They are great nurses, teachers, and event planners."}}'),
('ISTP', 'en', '{"name":"Virtuoso","introduction":"Virtuosos (ISTP) love to explore with their hands and their eyes. They are natural makers, moving from project to project, building the useful and the superfluous for the fun of it.","strengths_weaknesses":{"title":"Strengths & Weaknesses","introduction":"Virtuosos are masters of all kinds of tools.","strengths":[{"title":"Optimistic","description":"They are cheerful and good-natured."},{"title":"Creative","description":"They are practical and imaginative."},{"title":"Spontaneous","description":"They are relaxed and flexible."}],"weaknesses":[{"title":"Private","description":"They are difficult to get to know."},{"title":"Easily bored","description":"They dislike long-term commitments."},{"title":"Insensitive","description":"They can be blunt and miss emotional cues."}]},"romantic_relationships":{"title":"Romantic Relationships","introduction":"Virtuosos are unpredictable and exciting partners.","conclusion":"They enjoy relationships that are full of action."},"friendships":{"title":"Friendships","introduction":"Virtuoso friendships are based on shared activities.","conclusion":"They love to explore new hobbies with friends."},"parenthood":{"title":"Parenthood","introduction":"Virtuoso parents are hands-on and permissive.","conclusion":"They give their children a lot of freedom."},"career_paths":{"title":"Career Paths","introduction":"Virtuosos are natural engineers and mechanics.","conclusion":"They excel at careers that require hands-on work."}}'),
('ISFP', 'en', '{"name":"Adventurer","introduction":"Adventurers (ISFP) are true artists. They live in a colorful, sensual world, inspired by connections with people and ideas. They are always ready to explore and experience something new.","strengths_weaknesses":{"title":"Strengths & Weaknesses","introduction":"Adventurers are charming and artistic.","strengths":[{"title":"Charming","description":"They are relaxed and warm."},{"title":"Imaginative","description":"They are creative and artistic."},{"title":"Curious","description":"They love to explore and experiment."}],"weaknesses":[{"title":"Fiercely independent","description":"They dislike commitment and rules."},{"title":"Unpredictable","description":"They can be impulsive."},{"title":"Easily stressed","description":"They live in the moment and dislike planning."}]},"romantic_relationships":{"title":"Romantic Relationships","introduction":"Adventurers are spontaneous and exciting partners.","conclusion":"They shower their loved ones with affection."},"friendships":{"title":"Friendships","introduction":"Adventurer friendships are full of surprises.","conclusion":"They are always up for an adventure."},"parenthood":{"title":"Parenthood","introduction":"Adventurer parents are laid-back and fun.","conclusion":"They enjoy every moment with their children."},"career_paths":{"title":"Career Paths","introduction":"Adventurers need a career that allows for self-expression.","conclusion":"They are often artists, designers, or musicians."}}'),
('ESTP', 'en', '{"name":"Entrepreneur","introduction":"Entrepreneurs (ESTP) are the ultimate people persons. They are energetic and live on the edge. They are the center of attention and love drama, passion, and pleasure.","strengths_weaknesses":{"title":"Strengths & Weaknesses","introduction":"Entrepreneurs have an irresistible pull.","strengths":[{"title":"Bold","description":"They are daring and direct."},{"title":"Perceptive","description":"They are good at noticing small changes."},{"title":"Sociable","description":"They are great at networking."}],"weaknesses":[{"title":"Insensitive","description":"They can be blunt and tactless."},{"title":"Impatient","description":"They live in the fast lane."},{"title":"Risk-prone","description":"They can be reckless."}]},"romantic_relationships":{"title":"Romantic Relationships","introduction":"Entrepreneurs are thrilling and passionate partners.","conclusion":"Their relationships are never boring."},"friendships":{"title":"Friendships","introduction":"Entrepreneurs are the life of the party.","conclusion":"They have a large group of friends."},"parenthood":{"title":"Parenthood","introduction":"Entrepreneur parents are playful and energetic.","conclusion":"They encourage their children to take risks."},"career_paths":{"title":"Career Paths","introduction":"Entrepreneurs are natural salespeople and performers.","conclusion":"They thrive in high-stakes environments."}}'),
('ESFP', 'en', '{"name":"Entertainer","introduction":"Entertainers (ESFP) are born performers. They love the spotlight and are always ready to put on a show. They are spontaneous, energetic, and enthusiastic people.","strengths_weaknesses":{"title":"Strengths & Weaknesses","introduction":"Entertainers are the life of the party.","strengths":[{"title":"Original","description":"They have a unique sense of style."},{"title":"Practical","description":"They have excellent people skills."},{"title":"Observant","description":"They are very aware of others' feelings."}],"weaknesses":[{"title":"Conflict-averse","description":"They avoid difficult conversations."},{"title":"Easily bored","description":"They dislike routine."},{"title":"Sensitive","description":"They are very sensitive to criticism."}]},"romantic_relationships":{"title":"Romantic Relationships","introduction":"Entertainers are generous and supportive partners.","conclusion":"They are always looking for ways to please their partner."},"friendships":{"title":"Friendships","introduction":"Entertainer friendships are fun and spontaneous.","conclusion":"They are always ready for a good time."},"parenthood":{"title":"Parenthood","introduction":"Entertainer parents are fun-loving and playful.","conclusion":"They are their children's biggest fans."},"career_paths":{"title":"Career Paths","introduction":"Entertainers are drawn to careers in the arts and entertainment.","conclusion":"They are natural performers, stylists, and tour guides."}}'); 